#include "stdlib/stats/base/dists/erlang/entropy.h"
#include "stdlib/math/base/assert/is_positive_integer.h"
#include "stdlib/math/base/special/digamma.h"
#include "stdlib/math/base/special/gamma.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/math/base/assert/is_nan.h"


/**
* Returns the differential entropy for a erlang distribution with shape parameter `k` and rate parameter `lambda`.
*
* @param k         shape parameter
* @param lambda    rate parameter
* @returns         differential entropy
*
* @example
* double y = stdlib_base_dists_erlang_entropy( 1.0, 1.0 );
* // returns ~1.0
*
* @example
* double y = stdlib_base_dists_erlang_entropy( 4.0, 12.0 );
* // returns ~-0.462
*
* @example
* double y = stdlib_base_dists_erlang_entropy( 8.0, 2.0 );
* // returns ~1.723
*
* @example
* double y = stdlib_base_dists_erlang_entropy( 1.5, 2.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_erlang_entropy( 1.0, -0.1 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_erlang_entropy( -0.1, 1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_erlang_entropy( 2.0, NaN );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_erlang_entropy( NaN, 2.0 );
* // returns NaN
*/
double stdlib_base_dists_erlang_entropy( const double k, const double lambda ) {
    if (
		!stdlib_base_is_positive_integer( k ) ||
		stdlib_base_is_nan( lambda ) ||
		lambda <= 0.0
	) {
		return 0.0 / 0.0;
	}
	return ( ( 1-k ) * stdlib_base_digamma( k ) ) + stdlib_base_ln( stdlib_base_gamma( k ) / lambda ) + k;
}
